output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Shopping carts are prohibited in single-file shelf aisles flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "A shopper must not move a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "If a shopper parks or lets go of a cart, they are obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "hands_free_single_file_pickup",
    "text": "Shelf interactions inside single-file shelf aisles must be performed without holding a cart.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "return_to_wide_aisle_after_single_file_pickup",
    "text": "After taking an item from a single-file shelf aisle, the shopper is obliged to return to a wide aisle.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "singleFileShelfPickup": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "singleFileShelfPickup",
      "discharge": "wideAisle"
    }
  },
  {
    "id": "retrieve_cart_at_aisle_mouth",
    "text": "When a shopper returns without a cart to the mouth of a pedestrian-only shelf aisle, they are obliged to pick the cart back up there.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessAtAisleMouth": {
          "and": [
            "pedestrianAisleMouth",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "retrieveCart": {
          "pre": {
            "and": [
              "cartlessAtAisleMouth",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessAtAisleMouth",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "one_way_cart_traffic_in_wide_aisles",
    "text": "In cart-traffic aisles, carts must not be pushed westward against the aisle flow.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartTrafficAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "cartTrafficAisle",
          "W"
        ]
      }
    }
  },
  {
    "id": "cart_required_for_cart_accessible_shelf",
    "text": "Shelf interactions outside pedestrian-only single-file aisles should be done with a cart.",
    "abstraction": {
      "state_properties": {
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelvesBothSides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartAccessibleShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfFace",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
